import { useId, useMemo, useState } from "react";
import { fmtUsd, signed } from "../data/eventEngine";
import type { DashboardSnapshot } from "../data/types";

interface EquityPanelProps {
  snapshot: DashboardSnapshot;
}

const W = 1000;
const H = 272;
const PLOT = { left: 10, right: 972, top: 18, bottom: 196 };
const VOLUME_TOP = 210;
const VOLUME_BOTTOM = 258;

interface HoverState {
  index: number;
  value: number;
  day: number;
}

export function EquityPanel({ snapshot }: EquityPanelProps) {
  const rawId = useId();
  const gradientId = `equity-${rawId.replace(/[^a-zA-Z0-9]/g, "")}`;
  const glowId = `glow-${rawId.replace(/[^a-zA-Z0-9]/g, "")}`;
  const [hover, setHover] = useState<HoverState | null>(null);
  const series = snapshot.balanceSeries.length > 1 ? snapshot.balanceSeries : [snapshot.balance, snapshot.balance];
  const bars = snapshot.candles.slice(-series.length);

  const geometry = useMemo(() => {
    const minRaw = Math.min(...series);
    const maxRaw = Math.max(...series);
    const rawRange = maxRaw - minRaw || 1;
    const min = minRaw - rawRange * 0.22;
    const max = maxRaw + rawRange * 0.16;
    const range = max - min || 1;
    const plotW = PLOT.right - PLOT.left;
    const plotH = PLOT.bottom - PLOT.top;
    const xFor = (index: number): number => PLOT.left + (index / Math.max(1, series.length - 1)) * plotW;
    const yFor = (value: number): number => PLOT.top + (1 - (value - min) / range) * plotH;
    const points = series.map((value, index) => [xFor(index), yFor(value)] as const);
    const line = points.map(([x, y], index) => `${index === 0 ? "M" : "L"}${x.toFixed(2)},${y.toFixed(2)}`).join(" ");
    const area = `${line} L${PLOT.right},${PLOT.bottom} L${PLOT.left},${PLOT.bottom} Z`;
    const maxVolume = Math.max(...bars.map((bar) => bar.volume), 1);
    const barSlot = plotW / Math.max(1, bars.length);
    return { min, max, range, xFor, yFor, points, line, area, maxVolume, barSlot };
  }, [series, bars]);

  const latest = geometry.points[geometry.points.length - 1];
  const up = snapshot.pnl >= 0;
  const hoverPoint = hover ? geometry.points[hover.index] : null;
  const hoverLeft = hover ? (hover.index / Math.max(1, series.length - 1)) * 100 : 0;

  const handlePointer = (event: React.PointerEvent<SVGSVGElement>): void => {
    const rect = event.currentTarget.getBoundingClientRect();
    if (!rect.width) return;
    const ratio = Math.min(1, Math.max(0, (event.clientX - rect.left) / rect.width));
    const index = Math.round(ratio * (series.length - 1));
    setHover({ index, value: series[index], day: Math.max(1, snapshot.day - Math.floor((series.length - 1 - index) / 30)) });
  };

  return (
    <section className="panel equity-panel" data-testid="equity-panel" aria-labelledby="equity-title">
      <header className="panel-head equity-head">
        <div className="panel-heading">
          <span className="panel-kicker">BALANCE // DAY {snapshot.day} // DOPE</span>
          <h2 id="equity-title">Desk equity</h2>
        </div>
        <div className="equity-readout">
          <div className={`pnl-chip ${up ? "pnl-up" : "pnl-down"}`}>
            {up ? "▲" : "▼"} {signed(snapshot.pnl, 0)} USD <span>({signed(snapshot.pnlPct, 2)}%)</span>
          </div>
          <div className="equity-balance" aria-label={`Desk balance ${fmtUsd(snapshot.balance, 2)}`}>
            <span>$</span>
            {Math.floor(snapshot.balance).toLocaleString("en-US")}
            <span className="cents">.{(snapshot.balance % 1).toFixed(2).slice(1)}</span>
          </div>
        </div>
      </header>

      <div className="chart-wrap">
        <svg
          className="equity-chart"
          viewBox={`0 0 ${W} ${H}`}
          preserveAspectRatio="none"
          role="img"
          aria-label={`Equity curve across ${series.length} ticks. Latest ${fmtUsd(snapshot.balance, 2)}, profit and loss ${signed(snapshot.pnl, 0)} dollars.`}
          data-testid="equity-chart"
          onPointerMove={handlePointer}
          onPointerLeave={() => setHover(null)}
        >
          <defs>
            <linearGradient id={gradientId} x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stopColor="#79ffb2" stopOpacity="0.35" />
              <stop offset="55%" stopColor="#4bdc92" stopOpacity="0.12" />
              <stop offset="100%" stopColor="#4bdc92" stopOpacity="0" />
            </linearGradient>
            <filter id={glowId} x="-10%" y="-40%" width="120%" height="180%">
              <feGaussianBlur stdDeviation="5" result="blur" />
              <feMerge>
                <feMergeNode in="blur" />
                <feMergeNode in="SourceGraphic" />
              </feMerge>
            </filter>
          </defs>

          {[0, 0.25, 0.5, 0.75, 1].map((tick) => {
            const y = PLOT.top + (PLOT.bottom - PLOT.top) * tick;
            const value = geometry.max - geometry.range * tick;
            return (
              <g key={`grid-${tick}`}>
                <line x1={PLOT.left} x2={PLOT.right} y1={y} y2={y} className="chart-grid" />
                <text x={PLOT.right} y={y - 3} textAnchor="end" className="chart-axis-label">
                  {Math.round(value).toLocaleString("en-US")}
                </text>
              </g>
            );
          })}

          <path d={geometry.area} fill={`url(#${gradientId})`} />
          <path d={geometry.line} className="equity-line" filter={`url(#${glowId})`} />
          <path d={geometry.line} className="equity-line equity-line--core" />

          {latest ? (
            <g>
              <line x1={PLOT.left} x2={PLOT.right} y1={latest[1]} y2={latest[1]} className="chart-level" />
              <circle cx={latest[0]} cy={latest[1]} r="5.5" className="equity-pulse" />
              <circle cx={latest[0]} cy={latest[1]} r="2.6" className="equity-dot" />
            </g>
          ) : null}

          {bars.map((bar, index) => {
            const height = (bar.volume / geometry.maxVolume) * (VOLUME_BOTTOM - VOLUME_TOP - 6);
            const x = geometry.xFor(index) - 2;
            return (
              <rect
                key={`vol-${bar.t}`}
                x={x}
                y={VOLUME_BOTTOM - height}
                width={3}
                height={Math.max(1, height)}
                className={bar.close >= bar.open ? "volume-bar volume-up" : "volume-bar volume-down"}
              />
            );
          })}

          {hoverPoint ? (
            <g>
              <line x1={hoverPoint[0]} x2={hoverPoint[0]} y1={PLOT.top} y2={VOLUME_BOTTOM} className="chart-crosshair" />
              <circle cx={hoverPoint[0]} cy={hoverPoint[1]} r="4" className="hover-dot" />
            </g>
          ) : null}

          <text x={PLOT.left} y={H - 2} className="chart-axis-label">-{series.length} TICKS</text>
          <text x={PLOT.right} y={H - 2} textAnchor="end" className="chart-axis-label">NOW // {snapshot.sessionTime}</text>
        </svg>

        {hover ? (
          <div className="chart-tooltip" style={{ left: `${Math.min(84, Math.max(12, hoverLeft))}%` }}>
            <span>DAY {String(hover.day).padStart(2, "0")} / TICK {String(snapshot.seq - (series.length - 1 - hover.index)).padStart(4, "0")}</span>
            <strong>{fmtUsd(hover.value, 2)}</strong>
          </div>
        ) : null}
      </div>

      <footer className="equity-foot">
        <span><i className="legend-dot legend-dot--mint" /> EQUITY</span>
        <span><i className="legend-dot legend-dot--pink" /> VOLUME</span>
        <span>PEAK <b>{fmtUsd(snapshot.peakBalance, 0)}</b></span>
        <span>PNL <b className={up ? "tone-mint" : "tone-red"}>{signed(snapshot.pnlPct, 2)}%</b></span>
        <span className="equity-foot__hint">HOVER THE CURVE TO INSPECT A TICK</span>
      </footer>
    </section>
  );
}
